{# This Template generates JSON with Media representations to be used as background
Updated April 28th 2026 / NYPR Front page
Structures passed from Archipelago are
- node
  The full Node entity
- data
  The Full JSON Structure converted in an Array
- iiif_server
  The publicly available IIIF Server (Global Setting)
Since JSON was decoded into the 'data' values are valid PHP but could not
be valid JSON when outputting. So We use data.description|json_encode|raw
Without Double quotes.
#}
{# <---- SETUP ---> #}
{# -- The Desired width -- #}
{% set width = 1200 %}
{# -- The IIIF Server URLS -- #}
{% set Webserverurl =  url('<front>')|render|replace({':8001/':''}) ~ ':8183/iiif/2/' %}
{% set IIIFserverurl = iiif_server ? iiif_server ~ '/': Webserverurl %}
{# -- Node Info -- #}
{% if node.id %}
  {% set nodeurl = url('entity.node.canonical', {'node': node.id}, {'absolute': true}) %}
{% else %}
  {% set nodeurl = '<current>' ~ '/iiif/manifest' %}
{% endif%}
{# -- Language -- #}
{% set len = language.getId() ? language.getId() : "en" %}
{# --THIS WILL BE THE IMAGE IIIF URL. CAN HAVE A DEFAULT VALUE IN CASE OF FAILURE THERE IS ALWAYS A GENERIC THUMB-- #}
{# -- NOTE: for loops are scoped so if we only define source inside one it will not be accesible from the outside- #}
{% set source = '' %}
{# <---- END SETUP --> #}
{#  We will test for 3 main options
1.- Images
2.- PDF
3.- Movies
#}
{% apply spaceless %}
{% if attribute(data, 'as:image')|length > 0 %}
  {% set document  = data['as:image']|first %}
  {# if the default size is smaller than the source use the source one #}
  {% if document['flv:exif'].ImageWidth is defined and document['flv:exif'].ImageWidth < width %}
     {% set width = document['flv:exif'].ImageWidth %}
  {% endif %}
  {% set cantaloupeid  = IIIFserverurl ~ document['url']|replace({'s3://':''})|replace({'private://':''})|url_encode %}
  {% set source = cantaloupeid ~ "/full/" ~ width  ~ ",/0/default.jpg" %}
{% elseif attribute(data, 'as:document')|length > 0 %}
  {% set break = false %}
  {% for document in data['as:document']%}
{#- WIZARDLY UPDATED BY ARCHIPELAGO -#}
{%  if not break %}
  {# this is just an example, we  allow every PDF here but we can also filter by pronom id "info:pronom/fmt/17" or info:pronom/fmt/18 #}
    {% if document['flv:exif'].MIMEType == "application/pdf" and document['flv:exif'].PageCount > 0 %}
      {% set cantaloupeid  = IIIFserverurl ~ document['url']|replace({'s3://':''})|replace({'private://':''})|url_encode %}
      {% set source = cantaloupeid ~ "/pct:0,40,100,60/" ~ width  ~ ",/0/default.jpg?page=1" %}
      {% set break = true %}
    {% endif%}
  {#- WIZARDLY UPDATED BY ARCHIPELAGO -#}
{% endif %}
{% endfor %}
{% endif%}
{# <----START OUTPUT --> #}
{% set background_image = 'background-image: url("'~ source ~'"); background-attachment: fixed; background-position: 50% 50%; background-repeat: no-repeat no-repeat; background-size: cover;' %}
{% set ado_link = '<a href="' ~  nodeurl|render ~'" alt="'~ node.label ~'" hreflang="' ~ len~'">' ~ node.label ~ '</a>' %}
<section class="bgimage" style="{{ background_image }};height: 100vh;">
  <div class="container pt-5">
    <div class="row frontpage-panel col-xxl-5 col-xl-6 col-lg-7 col-md-9 col-sm-12 col-xs-12 clearfix">
    </div>
    <div class="p-3 mx-5 my-5 align-content-lg-right border-2 rounded row" style="background:rgba(255,255,255,0.90);">
        <div class="col-xxl-4 col-xl-4 col-lg-4 col-md-4 col-sm-12 col-xs-12">
        <img src="/sites/default/files/NYPR-Commons.png" alt="NYPR Commons logo - New York Public Radio's Media Library and Archives" class="img-fluid d-flex align-top">
        </div>
        <div class="col-xxl-8 col-xl-8 col-lg-8 col-md-8 col-sm-12 col-xs-12 my-5">{{ drupal_entity('block','archipelago_subtheme_chiloe_exposedformsolr_search_page',check_access=false) }} </div>
        {# ---- Login: visible to anonymous users only added by Dylan ---- #}
        {% if not logged_in %}
        <div class="col-12 front-login-cta" style="padding-left:0;">
          <hr class="front-login-divider">
          <div style="margin-left:0;padding-left:0;">{{ drupal_menu('login-options-nypr') }}</div>
          <p class="front-login-prompt" style="margin-left:0;padding-left:0;">Please log in to search and access materials.</p>
        </div>
        {% endif %}
        {# ---- END LOGIN ---- #}
    </div>
    <div class="container pt-5">
      <span class="p-3 mx-5 align-content-lg-center justify-content-end border-2 rounded" style="background:rgba(255,255,255,0.90);">
     {{  node.label }}
      </div>
  </div>
</section>
{% endapply %}
